function buildTaperTodayTasks(days,total){
  const alloc=taperTaskAllocation(total,days);
  const routes=actionableReviewJourneys().length,due=dueQuestions().length;
  const weak=weakestSkill();

  if(days<=0){
    return [{
      type:'warmup',icon:'☀️',bg:'yellow',
      title:'受験前ウォームアップ 3問',
      desc:'既習問題を中心に3問だけ確認。新規教材・長時間模試・追い込みは行いません。',
      minutes:total
    }];
  }

  if(days===1){
    return [
      {
        type:'taperReview',icon:'🧠',bg:'green',
        title:'前日の復習 5問まで',
        desc:routes?`復習ルート ${routes}件から優先`:due?`期限/低保持 ${due}問から最大5問`:`「${weak}」を最大5問だけ確認`,
        minutes:alloc.review
      },
      {
        type:'warmup',icon:'🌙',bg:'yellow',
        title:'軽いウォームアップ 3問',
        desc:'解き慣れた既習問題だけで感覚を確認。新しい範囲は増やしません。',
        minutes:alloc.boss
      }
    ].filter(t=>t.minutes>0);
  }

  const focus=taperFocusRecommendation(days);
  const tasks=[
    {
      type:'taperReview',icon:'🧠',bg:'green',
      title:days<=3?'直前復習 5問':'記憶の復習',
      desc:routes?`復習ルート ${routes}件を優先`:due?`期限/低保持 ${due}問を優先`:`今日の期限はなし。「${weak}」を維持`,
      minutes:alloc.review
    },
    {
      type:'finalFocus',icon:focus.icon,bg:'blue',
      title:focus.title,desc:focus.desc,
      minutes:alloc.lesson,focus
    }
  ];

  if(days>=4&&alloc.subjectB>=10){
    const b=nextBChoice(alloc.subjectB);
    tasks.push({
      type:'subjectB',icon:'💻',bg:'purple',
      title:b.mode==='trace'?`科目B：${b.title}`:b.mode==='security'?`科目B：${b.title}`:b.title,
      desc:'長時間の総合実戦ではなく、短い既習演習を1つ',
      minutes:alloc.subjectB,bmode:b.mode,bid:b.id
    });
  }else if(alloc.subjectB>0){
    tasks[1].minutes+=alloc.subjectB;
  }

  tasks.push({
    type:'boss',icon:'👑',bg:'yellow',
    title:'直前総合チェック',
    desc:'判断3問＋適用2問。新規知識ではなく、使えるかだけを5問で確認。',
    minutes:alloc.boss
  });
  return tasks.filter(t=>t.minutes>0);
}

function buildTodayTasks(){
  const daysNow=examDaysRemaining();
  const totalNow=effectiveStudyMinutes();
  if(daysNow!=null&&daysNow>=0&&daysNow<=7)return buildTaperTodayTasks(daysNow,totalNow);
  const alloc=taskAllocation(totalNow);
  const routes=actionableReviewJourneys().length;
  const due=dueQuestions().length;
  const lesson=nextLessonChoice();
  const b=nextBChoice(alloc.subjectB);
  const bMinutes=(b.mode==='compound'||b.mode==='securityMock')?Math.min(20,alloc.subjectB):alloc.subjectB;
  const lessonMinutes=alloc.lesson+Math.max(0,alloc.subjectB-bMinutes);
  const weak=weakestSkill();
  const days=examDaysRemaining();
  const finalPhase=days!=null&&days<=14;

  const rxReady=window.FEQUEST_RX_READY===true;
  const rx=rxReady?recommendedPrescription():{kind:'knowledge',cat:lesson.skill,reason:'データ不足'};
  const rxMeta=rxReady?prescriptionMeta(rx):{icon:'📘',title:lesson.title,desc:'未完了教材を優先'};
  const useRx=rxReady && rx.kind!=='knowledge';

  let learnTask;
  if(lesson.complete){
    const focus=shortFinalFocusRecommendation();
    learnTask={
      type:'finalFocus',icon:focus.icon,bg:'blue',
      title:focus.title,desc:focus.desc,
      minutes:lessonMinutes,focus
    };
  }else if(useRx){
    learnTask={
      type:'prescription',icon:rxMeta.icon,bg:'blue',
      title:rxMeta.title,desc:`原因「${rx.reason}」に合わせて自動処方`,
      minutes:lessonMinutes,rx
    };
  }else{
    learnTask={
      type:'lesson',icon:'📘',bg:'blue',
      title:lesson.title,desc:`${lesson.skill}・未完了教材を優先`,
      minutes:lessonMinutes,lessonId:lesson.id
    };
  }

  return [
    {
      type:'review',icon:'🧠',bg:'green',
      title:'記憶の復習',
      desc:routes?`復習ルート ${routes}件を優先`:due?`復習期限の問題 ${due}問を優先`:`今日の復習期限はなし。「${weak}」を補強`,
      minutes:alloc.review
    },
    learnTask,
    {
      type:'subjectB',icon:'💻',bg:'purple',
      title:b.mode==='trace'?`プログラムトレース：${b.title}`:b.mode==='security'?`セキュリティ：${b.title}`:b.mode==='compound'?`複合演習：${b.title}`:b.mode==='securityMock'?b.title:`実戦：${b.title}`,
      desc:b.mode==='trace'?'科目B アルゴリズム':b.mode==='security'?'科目B 情報セキュリティ':b.mode==='compound'?'科目B アルゴリズム・20分実戦':b.mode==='securityMock'?'科目B セキュリティ・20分実戦':'科目B 実戦',
      minutes:bMinutes,bmode:b.mode,bid:b.id
    },
    {
      type:'boss',icon:'👑',bg:'yellow',
      title:finalPhase?'直前総合チェック':'今日の総合チェック',
      desc:finalPhase?'判断3問＋適用2問・分野を散らして5問':'全分野から5問・仕上げチェック',
      minutes:alloc.boss
    }
  ];
}

function examPaceStatus(){
  const days=examDaysRemaining(),baseline=Number(profile.settings?.studyMinutes)||60,remaining=estimateRemainingStudyMinutes(),recent=recentCalendarPace(),phase=examStudyPhase(days);
  if(days==null)return {hasExam:false,baseline,effective:baseline,remaining,recent,phase};
  if(days<0)return {hasExam:true,expired:true,days,baseline,effective:baseline,remaining,recent,phase};
  const available=Math.max(1,days),required=remaining/available,currentPace=recent.enough?recent.avg:baseline,paceSource=recent.enough?'recent':'plan';
  const projectedDays=currentPace>0?Math.ceil(remaining/currentPace):9999,projectedDate=new Date();projectedDate.setHours(12,0,0,0);projectedDate.setDate(projectedDate.getDate()+projectedDays);
  const slack=available-projectedDays;
  let status='danger';
  if(required<=0||currentPace>=required*1.20)status='good';else if(currentPace>=required*.95)status='ok';else if(currentPace>=required*.75)status='warn';
  const auto=profile.settings?.autoPace!==false,suggested=Math.max(baseline,roundUp5(required*1.10));
  const cap=taperStudyCap(days);
  const taper=cap!=null;
  const normalEffective=auto?Math.min(120,suggested):baseline;
  // 残り7日以内は「残学習量を全部消化する」ための追い込みを止める。
  // 標準時間が短い利用者は増やさず、長い利用者だけ段階的に上限を下げる。
  const effective=taper?Math.min(baseline,cap):normalEffective;
  const adjustedDays=effective>0?Math.ceil(remaining/effective):9999,maxDate=new Date();maxDate.setHours(12,0,0,0);maxDate.setDate(maxDate.getDate()+Math.ceil(remaining/120));
  return {hasExam:true,expired:false,days,baseline,remaining,recent,phase,required,currentPace,paceSource,projectedDays,projectedDate,slack,status,auto,effective,canRecover:adjustedDays<=available,maxDate,taper,taperCap:cap};
}

