function finishDiagnostic(){
  const cats={};
  DIAG_QUESTIONS.forEach((q,i)=>{
    if(!cats[q.category]) cats[q.category]={correct:0,total:0};
    cats[q.category].total++;
    if(diagAnswers[i]===q.answer) cats[q.category].correct++;
  });

  const scores={};
  Object.entries(cats).forEach(([cat,v])=>{
    scores[cat]=Math.round(v.correct/v.total*100);
  });

  // Categories with one diagnostic item are softened toward a neutral prior
  // so one mistake does not create an extreme 0/100 mastery estimate.
  Object.keys(profile.skills).forEach(cat=>{
    const raw = scores[cat];
    if(raw !== undefined){
      const sampleCount = cats[cat].total;
      const prior = profile.skills[cat] ?? 60;
      const weight = sampleCount >= 2 ? 0.65 : 0.45;
      profile.skills[cat]=Math.round(prior*(1-weight)+raw*weight);
    }
  });

  profile.diagnosticCompleted=true;
  profile.diagnosticScores=scores;
  profile.xp += 120;
  saveProfile();

  document.getElementById('diagQuiz').style.display='none';
  document.getElementById('diagResult').style.display='block';

  const grid=document.getElementById('diagResultGrid');
  grid.innerHTML='';
  sortedSkills().forEach(([cat,val])=>{
    const d=document.createElement('div');
    d.className='diag-result';
    d.innerHTML=`<div class="sub">${cat}</div><div class="diag-score">${val}%</div>`;
    grid.appendChild(d);
  });

  const weak=sortedSkills().slice(0,3).map(x=>x[0]);
  document.getElementById('diagResultAdvice').textContent=
    `まずは「${weak.join('・')}」を重点的に進めます。今日の学習は${effectiveStudyMinutes()}分を目安に自動調整します。`;
}

function renderAllocation(){
  const root=document.getElementById('planAllocation');if(!root)return;
  const total=effectiveStudyMinutes(),p=examPaceStatus(),a=taskAllocation(total);
  const taper=!!p.taper;
  const lessonLabel=taper&&p.days<=3?'既習の弱点補強':p.hasExam&&p.days<=30?'弱点学習':'新規学習';
  const bossLabel=taper&&p.days===0?'ウォームアップ':p.hasExam&&p.days<=14?'総合チェック':'総合チェック';
  const items=[['🧠','復習',a.review],['📘',lessonLabel,a.lesson],['💻','科目B',a.subjectB],['👑',bossLabel,a.boss]].filter(x=>x[2]>0);
  const note=document.getElementById('allocationPaceNote');
  if(note){
    if(taper)note.innerHTML=`<div class="pace-phase-banner"><b>${p.phase.icon} ${p.phase.name}</b>　今日の推奨 ${total}分。残り${p.days}日では、未完了量を追い掛けず新規学習を段階的に止めます。</div>`;
    else note.innerHTML=p.hasExam&&!p.expired?`<div class="pace-phase-banner"><b>${p.phase.icon} ${p.phase.name}</b>　今日の目標 ${total}分。試験日が近づくほど、新規学習を減らして復習・科目B・実戦確認へ配分を寄せます。</div>`:'標準学習時間を4つの学習枠に配分します。';
  }
  root.innerHTML=items.map(x=>`<div class="planner-row"><div style="font-size:21px">${x[0]}</div><div class="planner-row-copy"><div class="planner-label">${x[1]}</div></div><b>${x[2]}分</b></div>`).join('');
}

function renderDailyPlan(){
  const root=document.getElementById('dailyTaskList');
  if(!root) return;
  const rec=getDailyRecord();
  const tasks=ensureTodayPlanSnapshot();
  const total=Number(rec.targetMinutes)||tasks.reduce((s,t)=>s+(Number(t.minutes)||0),0)||effectiveStudyMinutes();
  const doneTasks=tasks.filter(t=>dailyTaskDone(rec,t));
  const doneMinutes=doneTasks.reduce((s,t)=>s+t.minutes,0);
  const pct=Math.min(100,Math.round(doneMinutes/total*100));

  document.getElementById('dailyProgressBar').style.width=pct+'%';
  document.getElementById('dailyProgressLabel').textContent=`${doneMinutes} / ${total}分`;
  document.getElementById('dailyDoneLabel').textContent=`${doneTasks.length} / ${tasks.length} 完了`;
  const pace=examPaceStatus();
  document.getElementById('todayPlanMeta').textContent=pace.hasExam&&!pace.expired
    ? `${pace.phase.name}・今日${total}分・復習待ち${reviewWorkloadCount()}件・弱点「${weakestSkill()}」`
    : `標準${total}分・復習待ち${reviewWorkloadCount()}件・弱点「${weakestSkill()}」`;
  const ready=calcReadiness();
  document.getElementById('homeReadiness').textContent=ready+'%';

  root.innerHTML='';
  tasks.forEach(t=>{
    const done=dailyTaskDone(rec,t);
    const d=document.createElement('div');
    d.className='daily-task'+(done?' done':'');
    d.innerHTML=`
      <div class="daily-task-icon ${t.bg}">${t.icon}</div>
      <div>
        <div class="daily-task-title">${learningHtml(t.title)}</div>
        <div class="daily-task-desc">${escapeHtml(t.desc)}</div>
      </div>
      <div class="daily-task-side">
        <div class="daily-task-time">${t.minutes}分</div>
        <button class="daily-task-btn">${done?'もう一度':'開始'}</button>
      </div>`;
    d.querySelector('button').onclick=()=>launchDailyTask(t);
    root.appendChild(d);
  });

  const resume=document.getElementById('todayResumeBtn');
  if(resume){
    const nextTask=tasks.find(t=>!dailyTaskDone(rec,t));
    if(nextTask){
      resume.disabled=false;
      resume.textContent=doneTasks.length?'続きから再開 →':'今日の学習を始める →';
      resume.onclick=()=>launchDailyTask(nextTask);
    }else{
      resume.disabled=true;
      resume.textContent='今日の学習は完了しました ✓';
      resume.onclick=null;
    }
  }
  const rightProgress=document.getElementById('rightDailyProgress'),rightNext=document.getElementById('rightDailyNext'),rightAction=document.getElementById('rightDailyAction');
  const nextTask=tasks.find(t=>!dailyTaskDone(rec,t));
  if(rightProgress)rightProgress.textContent=`${doneTasks.length}/${tasks.length}完了・${doneMinutes}/${total}分`;
  if(rightNext)rightNext.textContent=nextTask?`次は「${nextTask.title}」・目安${nextTask.minutes}分`:'今日の計画は完了しています。';
  if(rightAction){rightAction.disabled=!nextTask;rightAction.textContent=nextTask?'続きから再開 →':'今日の学習は完了 ✓';rightAction.onclick=nextTask?()=>launchDailyTask(nextTask):null;}
}

function taperStudyCap(days=examDaysRemaining()){
  if(days==null||days<0||days>7)return null;
  if(days>=4)return 45;
  if(days>=2)return 30;
  if(days===1)return 15;
  return 10;
}

function taperTaskAllocation(total,days){
  total=Math.max(5,Math.round(Number(total)||10));
  if(days<=0)return {review:0,lesson:0,subjectB:0,boss:total};
  if(days===1)return {review:Math.max(5,total-5),lesson:0,subjectB:0,boss:Math.min(5,total)};
  if(days<=3)return {review:10,lesson:Math.max(5,total-15),subjectB:0,boss:5};
  if(total<=30)return {review:10,lesson:10,subjectB:5,boss:5};
  return {review:15,lesson:10,subjectB:10,boss:Math.max(5,total-35)};
}

function taskAllocation(total){
  total=Number(total)||effectiveStudyMinutes();const days=examDaysRemaining();
  if(days!=null&&days>=0&&days<=6)return taperTaskAllocation(total,days);
  if(days==null){if(total===30)return {review:5,lesson:10,subjectB:10,boss:5};if(total===45)return {review:5,lesson:15,subjectB:15,boss:10};if(total===90)return {review:15,lesson:30,subjectB:30,boss:15};if(total===60)return {review:10,lesson:20,subjectB:20,boss:10};}
  return allocateByRatios(total,examStudyPhase(days).ratios);
}

