  const taper=!!p.taper;
  const lessonLabel=taper&&p.days<=3?'既習の弱点補強':p.hasExam&&p.days<=30?'弱点学習':'新規学習';
  const bossLabel=taper&&p.days===0?'ウォームアップ':p.hasExam&&p.days<=14?'総合チェック':'総合チェック';
  const items=[['🧠','復習',a.review],['📘',lessonLabel,a.lesson],['💻','科目B',a.subjectB],['👑',bossLabel,a.boss]].filter(x=>x[2]>0);
  const note=document.getElementById('allocationPaceNote');
  if(note){
    if(taper)note.innerHTML=`<div class="pace-phase-banner"><b>${p.phase.icon} ${p.phase.name}</b>　今日の推奨 ${total}分。残り${p.days}日では、未完了量を追い掛けず新規学習を段階的に止めます。</div>`;
    else note.innerHTML=p.hasExam&&!p.expired?`<div class="pace-phase-banner"><b>${p.phase.icon} ${p.phase.name}</b>　今日の目標 ${total}分。試験日が近づくほど、新規学習を減らして復習・科目B・実戦確認へ配分を寄せます。</div>`:'標準学習時間を4つの学習枠に配分します。';
  }
  root.innerHTML=items.map(x=>`<div class="planner-row"><div style="font-size:21px">${x[0]}</div><div class="planner-row-copy"><div class="planner-label">${x[1]}</div></div><b>${x[2]}分</b></div>`).join('');
}

directLearnerFunctions.launchDailyTask:
function launchDailyTask(t){
  if(t.type==='warmup'){
    showScreen('problems');
    startQuiz('warmup');
    return;
  }
  if(t.type==='taperReview'){
    showScreen('problems');
    startQuiz('taperreview');
    return;
  }
  if(t.type==='review'){
    const j=actionableReviewJourneys()[0];
    if(j){
      startJourneyAction(j.id);
    }else{
      showScreen('problems');
      startQuiz('review');
    }
    return;
  }
  if(t.type==='lesson'){
    startLesson(t.lessonId);
    return;
  }
  if(t.type==='prescription'){
    if(t.rx?.kind==='knowledge') startLesson(pickLessonForSkill(t.rx.cat));
    else{
      showScreen('problems');
      startQuiz(rxMode(t.rx));
    }
    return;
  }
  if(t.type==='finalFocus'){
    launchFinalFocus(t.focus);
    return;
  }
  if(t.type==='subjectB'){
    showScreen('trace');
    if(t.bmode==='trace'){
      setBMode('trace');
      if(t.bid) startBExercise(t.bid);
    }else if(t.bmode==='security'){
      setBMode('security');
      if(t.bid) startSecurityScenario(t.bid);
    }else if(t.bmode==='compound'){
      setBMode('mock');
      startCompoundChallenge();
    }else if(t.bmode==='securityMock'){
      setBMode('security');
      startSecurityMock();
    }else{
      setBMode('mock');
    }
    return;
  }
  if(t.type==='boss'){
    showScreen('problems');
    startQuiz('boss');
  }
}
